// StyleSet holds all configurable styles.
type StyleSet struct {
	Basic          tcell.Style
	SavedSelection tcell.Style
	Selected       tcell.Style
	Query          tcell.Style
	QueryCursor    tcell.Style
	Matched        tcell.Style
	Prompt         tcell.Style
	Context        tcell.Style
}

func defaultStyles() *StyleSet {
	def := tcell.StyleDefault.Foreground(tcell.ColorDefault).Background(tcell.ColorDefault)
	return &StyleSet{
		Basic:          def,
		SavedSelection: def.Foreground(tcell.ColorBlack).Background(tcell.ColorTeal).Bold(true),
		Selected:       def.Background(tcell.ColorPurple).Underline(true),
		Query:          def,
		QueryCursor:    def.Reverse(true),
		Matched:        def.Foreground(tcell.ColorTeal),
		Prompt:         def,
		Context:        def.Bold(true),
	}
}

// CustomFilterConfig describes an external filter.
type CustomFilterConfig struct {
	Cmd             string   `json:"Cmd" yaml:"Cmd"`
	Args            []string `json:"Args" yaml:"Args"`
	BufferThreshold int      `json:"BufferThreshold" yaml:"BufferThreshold"`
}

// SingleKeyJumpConfig configures single key jump mode.
type SingleKeyJumpConfig struct {
	ShowPrefix bool `json:"ShowPrefix" yaml:"ShowPrefix"`
}

// OnCancelValue is a validated "success"/"error" value.
type OnCancelValue string

func (v *OnCancelValue) validate(s string) error {
	switch s {
	case "success", "error", "":
		*v = OnCancelValue(s)
		return nil
	}
	return fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"", s)
}

func (v *OnCancelValue) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return err
	}
	return v.validate(s)
}

func (v *OnCancelValue) UnmarshalYAML(node *yaml.Node) error {
	var s string
	if err := node.Decode(&s); err != nil {
		return err
	}
	return v.validate(s)
}

// HeightValue accepts either a string or a number.
type HeightValue string

func (v *HeightValue) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err == nil {
		*v = HeightValue(s)
		return nil
	}
	var n json.Number
	if err := json.Unmarshal(b, &n); err == nil {
		*v = HeightValue(n.String())
		return nil
	}
	return fmt.Errorf("invalid Height value: %s", string(b))
}

func (v *HeightValue) UnmarshalYAML(node *yaml.Node) error {
	*v = HeightValue(node.Value)
	return nil
}

// Config is the configuration file structure.
type Config struct {
	Prompt            string                        `json:"Prompt" yaml:"Prompt"`
	InitialFilter     string                        `json:"InitialFilter" yaml:"InitialFilter"`
	FuzzyLongestSort  bool                          `json:"FuzzyLongestSort" yaml:"FuzzyLongestSort"`
	StickySelection   bool                          `json:"StickySelection" yaml:"StickySelection"`
	SuppressStatusMsg bool                          `json:"SuppressStatusMsg" yaml:"SuppressStatusMsg"`
	OnCancel          OnCancelValue                 `json:"OnCancel" yaml:"OnCancel"`
	MaxScanBufferSize int                           `json:"MaxScanBufferSize" yaml:"MaxScanBufferSize"`
	ANSI              bool                          `json:"ANSI" yaml:"ANSI"`
	Height            HeightValue                   `json:"Height" yaml:"Height"`
	Layout            string                        `json:"Layout" yaml:"Layout"`
	Keymap            map[string]string             `json:"Keymap" yaml:"Keymap"`
	Action            map[string][]string           `json:"Action" yaml:"Action"`
	Style             map[string][]string           `json:"Style" yaml:"Style"`
	CustomFilter      map[string]CustomFilterConfig `json:"CustomFilter" yaml:"CustomFilter"`
	SingleKeyJump     SingleKeyJumpConfig           `json:"SingleKeyJump" yaml:"SingleKeyJump"`
	SelectionPrefix   string                        `json:"SelectionPrefix" yaml:"SelectionPrefix"`
	Use256Color       bool                          `json:"Use256Color" yaml:"Use256Color"`
}

func newConfig() *Config {
	return &Config{
		Keymap: map[string]string{},
	}
}

// locateConfigFile searches the standard locations for a configuration file.
func locateConfigFile() string {
	exists := func(p string) bool {
		st, err := os.Stat(p)
		return err == nil && !st.IsDir()
	}
	candidates := func(dir string) []string {
		return []string{
			filepath.Join(dir, "peco", "config.json"),
			filepath.Join(dir, "peco", "config.yaml"),
			filepath.Join(dir, "peco", "config.yml"),
		}
	}
	home := os.Getenv("HOME")
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		for _, c := range candidates(xdg) {
			if exists(c) {
				return c
			}
		}
	}
	if home != "" {
		for _, c := range candidates(filepath.Join(home, ".config")) {
			if exists(c) {
				return c
			}
		}
	}
	if dirs := os.Getenv("XDG_CONFIG_DIRS"); dirs != "" {
		for _, d := range strings.Split(dirs, ":") {
			if d == "" {
				continue
			}
			for _, c := range candidates(d) {
				if exists(c) {
					return c
				}
			}
		}
	}
	if home != "" {
		for _, c := range []string{
			filepath.Join(home, ".peco", "config.json"),
			filepath.Join(home, ".peco", "config.yaml"),
			filepath.Join(home, ".peco", "config.yml"),
		} {
			if exists(c) {
				return c
			}
		}
	}
	return ""
}

// readConfig reads the configuration file at path.
func (c *Config) readConfig(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("failed to open file %s: %s", path, err.Error())
	}
	defer f.Close()

	ext := strings.ToLower(filepath.Ext(path))
	if ext == ".yaml" || ext == ".yml" {
		data, err := io.ReadAll(f)
		if err != nil {
			return fmt.Errorf("failed to decode YAML: %s", err.Error())
		}
		if err := yaml.Unmarshal(data, c); err != nil {
			return fmt.Errorf("failed to decode YAML: %s", err.Error())
		}
	} else {
		dec := json.NewDecoder(f)
		if err := dec.Decode(c); err != nil {
			return fmt.Errorf("failed to decode JSON: %s", err.Error())
		}
	}
	if c.Layout != "" && !isValidLayout(c.Layout) {
		return fmt.Errorf("invalid layout type: %s", c.Layout)
	}
	return nil
}

func isValidLayout(s string) bool {
	switch s {
	case "top-down", "bottom-up", "top-down-query-bottom":
		return true
	}
	return false
}

var colorNames = map[string]tcell.Color{
	"default": tcell.ColorDefault,
	"black":   tcell.ColorBlack,
	"red":     tcell.ColorMaroon,
	"green":   tcell.ColorGreen,
	"yellow":  tcell.ColorOlive,
	"blue":    tcell.ColorNavy,
	"magenta": tcell.ColorPurple,
	"cyan":    tcell.ColorTeal,
	"white":   tcell.ColorSilver,
}

func parseColor(s string) (tcell.Color, bool) {
	if c, ok := colorNames[s]; ok {
		return c, true
	}
	if strings.HasPrefix(s, "#") && len(s) == 7 {
		v, err := strconv.ParseUint(s[1:], 16, 32)
		if err != nil {
			return 0, false
		}
		return tcell.NewHexColor(int32(v)), true
	}
	if n, err := strconv.Atoi(s); err == nil {
		if n >= 0 && n <= 255 {
			return tcell.PaletteColor(n), true
		}
	}
	return 0, false
}

// parseStyle converts a style spec list into a tcell style.
func parseStyle(spec []string) tcell.Style {
	st := tcell.StyleDefault.Foreground(tcell.ColorDefault).Background(tcell.ColorDefault)
	for _, s := range spec {
		switch s {
		case "bold":
			st = st.Bold(true)
			continue
		case "underline":
			st = st.Underline(true)
			continue
		case "reverse":
			st = st.Reverse(true)
			continue
		case "blink":
			st = st.Blink(true)
			continue
		case "on_bold":
			st = st.Blink(true)
			continue
		}
		if strings.HasPrefix(s, "on_") {
			if c, ok := parseColor(s[3:]); ok {
				st = st.Background(c)
			}
			continue
		}
		if c, ok := parseColor(s); ok {
			st = st.Foreground(c)
		}
	}
	return st
}

func (c *Config) applyStyles(ss *StyleSet) {
	for name, spec := range c.Style {
		st := parseStyle(spec)
		switch name {
		case "Basic":
			ss.Basic = st
		case "SavedSelection":
			ss.SavedSelection = st
		case "Selected":
			ss.Selected = st
		case "Query":
			ss.Query = st
		case "QueryCursor":
			ss.QueryCursor = st
		case "Matched":
			ss.Matched = st
		case "Prompt":
			ss.Prompt = st
		case "Context":
			ss.Context = st
		}
	}
}
