                    self.cells[y] = [(' ', '') for _ in range(self.cols)]
            else:
                self.clear()
        elif final == 'K':
            for x in range(self.cx, self.cols): self.cells[self.cy][x] = (' ', '')
        elif final == 'm':
            if params == '' or params == '0':
                self.style = ''
            else:
                self.style = self.merge(self.style, params)
