            elif p == '49' or (p.isdigit() and 40 <= int(p) <= 47) or (p.isdigit() and 100 <= int(p) <= 107):
                attrs = {a for a in attrs if not (a.isdigit() and (40 <= int(a) <= 49 or 100 <= int(a) <= 107)) and not a.startswith('48;')}
                if p != '49': attrs.add(p)
            i += 1
