            elif p == '22': attrs.discard('1')
            elif p == '24': attrs.discard('4')
            elif p == '27': attrs.discard('7')
            elif p == '39' or (p.isdigit() and 30 <= int(p) <= 37) or (p.isdigit() and 90 <= int(p) <= 97):
