        return ';'.join(sorted(attrs))
    def text(self):
        return '\n'.join(''.join(ch for ch, _ in row).rstrip() for row in self.cells)
    def styled(self):
        out = []
        for row in self.cells:
            s = ''; last = None
            for ch, st in row:
                if st != last:
                    s += '{%s}' % st; last = st
                s += ch
            out.append(s.rstrip())
        return '\n'.join(out)
