// Keymap is a trie of key sequences to actions.
type keymapNode struct {
	action   *Action
	children map[keySpec]*keymapNode
}

func newKeymapNode() *keymapNode {
	return &keymapNode{children: map[keySpec]*keymapNode{}}
}

type Keymap struct {
	root *keymapNode
}

func newKeymap() *Keymap {
	return &Keymap{root: newKeymapNode()}
}

func (km *Keymap) bind(seq []keySpec, a *Action) {
	n := km.root
	for _, k := range seq {
		c, ok := n.children[k]
		if !ok {
			c = newKeymapNode()
			n.children[k] = c
		}
		n = c
	}
	n.action = a
}

// lookup follows the sequence; returns the node (nil if no such path).
func (km *Keymap) lookup(seq []keySpec) *keymapNode {
	n := km.root
	for _, k := range seq {
		c, ok := n.children[k]
		if !ok {
			return nil
		}
		n = c
	}
	return n
}

var defaultKeymap = map[string]string{
	"Esc":        "peco.Cancel",
	"C-c":        "peco.Cancel",
	"Enter":      "peco.Finish",
	"C-f":        "peco.ForwardChar",
	"C-a":        "peco.BeginningOfLine",
	"C-b":        "peco.BackwardChar",
	"C-d":        "peco.DeleteForwardChar",
	"C-e":        "peco.EndOfLine",
	"C-k":        "peco.KillEndOfLine",
	"C-u":        "peco.KillBeginningOfLine",
	"BS":         "peco.DeleteBackwardChar",
	"C-8":        "peco.DeleteBackwardChar",
	"C-w":        "peco.DeleteBackwardWord",
	"C-g":        "peco.SelectNone",
	"C-n":        "peco.SelectDown",
	"C-p":        "peco.SelectUp",
	"C-r":        "peco.RotateFilter",
	"C-t":        "peco.ToggleQuery",
	"C-v":        "peco.ViewAround",
	"C-Space":    "peco.ToggleSelectionAndSelectNext",
	"ArrowUp":    "peco.SelectUp",
	"ArrowDown":  "peco.SelectDown",
	"ArrowLeft":  "peco.ScrollPageUp",
	"ArrowRight": "peco.ScrollPageDown",
	"Pgup":       "peco.ScrollPageUp",
	"Pgdn":       "peco.ScrollPageDown",
	"Home":       "peco.ScrollFirstItem",
	"End":        "peco.ScrollLastItem",
}

// buildKeymap constructs the keymap from defaults plus configuration.
func buildKeymap(cfg *Config, actions map[string]*Action) (*Keymap, error) {
	km := newKeymap()
	for name, act := range defaultKeymap {
		ks, ok := parseKeyName(name)
		if !ok {
			continue
		}
		km.bind([]keySpec{ks}, actions[act])
	}
	for seqName, actName := range cfg.Keymap {
		a, ok := actions[actName]
		if !ok {
			return nil, fmt.Errorf("failed to apply key bindings: failed to resolve action name %s: could not resolve %s: no such action", actName, actName)
		}
		var seq []keySpec
		valid := true
		for _, part := range strings.Split(seqName, ",") {
			ks, ok := parseKeyName(part)
			if !ok {
				valid = false
				break
			}
			seq = append(seq, ks)
		}
		if !valid || len(seq) == 0 {
			continue
		}
		km.bind(seq, a)
	}
	return km, nil
}
