	if b == nil || i < 0 || i >= len(b.lines) {
		return nil
	}
	return b.lines[i]
}

// mergeRanges sorts and merges overlapping or adjacent ranges.
func mergeRanges(r [][2]int) [][2]int {
	if len(r) <= 1 {
		return r
	}
	// insertion sort (small)
	for i := 1; i < len(r); i++ {
		for j := i; j > 0 && r[j][0] < r[j-1][0]; j-- {
			r[j], r[j-1] = r[j-1], r[j]
		}
	}
	out := r[:1]
	for _, x := range r[1:] {
		last := &out[len(out)-1]
		if x[0] <= last[1] {
			if x[1] > last[1] {
				last[1] = x[1]
			}
		} else {
			out = append(out, x)
		}
	}
	return out
}
