package main

import (
	"strconv"
	"strings"

	"github.com/gdamore/tcell/v2"
)

// ansiSpan describes a styled region of the display string.
type ansiSpan struct {
	start, end int
	fg, bg     tcell.Color
	attrs      tcell.AttrMask
}

type sgrState struct {
	fg, bg tcell.Color
	attrs  tcell.AttrMask
}

func (s sgrState) isDefault() bool {
	return s.fg == tcell.ColorDefault && s.bg == tcell.ColorDefault && s.attrs == 0
}

func (s *sgrState) apply(params string) {
	if params == "" {
		*s = sgrState{}
		return
	}
	parts := strings.Split(params, ";")
	for i := 0; i < len(parts); i++ {
		n, err := strconv.Atoi(parts[i])
		if err != nil {
			if parts[i] == "" {
				n = 0
			} else {
				continue
			}
		}
		switch {
		case n == 0:
			*s = sgrState{}
		case n == 1:
			s.attrs |= tcell.AttrBold
		case n == 4:
			s.attrs |= tcell.AttrUnderline
		case n == 7:
			s.attrs |= tcell.AttrReverse
		case n >= 30 && n <= 37:
			s.fg = tcell.PaletteColor(n - 30)
		case n == 39:
			s.fg = tcell.ColorDefault
		case n >= 40 && n <= 47:
			s.bg = tcell.PaletteColor(n - 40)
		case n == 49:
			s.bg = tcell.ColorDefault
		case n == 38 || n == 48:
			if i+1 >= len(parts) {
				return
			}
			var c tcell.Color
			ok := false
			if parts[i+1] == "5" && i+2 < len(parts) {
				if v, err := strconv.Atoi(parts[i+2]); err == nil && v >= 0 && v <= 255 {
					c = tcell.PaletteColor(v)
					ok = true
				}
				i += 2
			} else if parts[i+1] == "2" && i+4 < len(parts) {
				r, e1 := strconv.Atoi(parts[i+2])
				g, e2 := strconv.Atoi(parts[i+3])
				b, e3 := strconv.Atoi(parts[i+4])
				if e1 == nil && e2 == nil && e3 == nil {
					c = tcell.NewRGBColor(int32(r&0xff), int32(g&0xff), int32(b&0xff))
					ok = true
				}
				i += 4
			} else {
				return
			}
			if ok {
				if n == 38 {
					s.fg = c
				} else {
					s.bg = c
				}
			}
		}
	}
}

// parseANSI strips CSI sequences from s, interpreting SGR sequences into spans.
func parseANSI(s string) (string, []ansiSpan) {
	if strings.IndexByte(s, 0x1b) < 0 {
		return s, nil
	}
	var b strings.Builder
	var spans []ansiSpan
	cur := sgrState{}
	spanStart := 0
	flush := func() {
		if b.Len() > spanStart && !cur.isDefault() {
			spans = append(spans, ansiSpan{start: spanStart, end: b.Len(), fg: cur.fg, bg: cur.bg, attrs: cur.attrs})
		}
		spanStart = b.Len()
	}
	i := 0
	for i < len(s) {
		c := s[i]
		if c == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && s[j] >= 0x30 && s[j] <= 0x3f {
				j++
			}
			pend := j
			for j < len(s) && s[j] >= 0x20 && s[j] <= 0x2f {
				j++
			}
			if j >= len(s) {
				// incomplete sequence: swallow the rest
				break
			}
			final := s[j]
			if final == 'm' {
				flush()
				cur.apply(s[i+2 : pend])
				spanStart = b.Len()
			}
			i = j + 1
			continue
		}
		if c == 0x1b && i+1 >= len(s) {
			break
		}
		b.WriteByte(c)
		i++
	}
	flush()
	return b.String(), spans
}
