package main

import (
	"bufio"
	"bytes"
	"context"
	"os/exec"
	"regexp"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

type queryTerm struct {
	text     string
	negative bool
}

// parseQuery splits the query into terms, handling negative terms.
func parseQuery(q string) []queryTerm {
	var terms []queryTerm
	for _, f := range strings.Fields(q) {
		switch {
		case f == "-" || f == "--":
			terms = append(terms, queryTerm{text: f})
		case strings.HasPrefix(f, "\\-"):
			terms = append(terms, queryTerm{text: f[1:]})
		case strings.HasPrefix(f, "-") && len(f) > 1:
			terms = append(terms, queryTerm{text: f[1:], negative: true})
		default:
			terms = append(terms, queryTerm{text: f})
		}
	}
	return terms
}

// isRefinement reports whether newQ narrows oldQ so that filtering the
// previous results is sufficient.
func isRefinement(oldQ, newQ string) bool {
	if oldQ == "" {
		return false
	}
	ot := parseQuery(oldQ)
	nt := parseQuery(newQ)
	if len(nt) < len(ot) {
		return false
	}
	for i, o := range ot {
		n := nt[i]
		if o.negative != n.negative {
			return false
		}
		if o.negative {
			if o.text != n.text {
				return false
			}
		} else if !strings.HasPrefix(n.text, o.text) {
			return false
		}
	}
	return true
}

// Filter is a query filter.
type Filter interface {
	Name() string
	// Compile prepares a matcher for the query; nil if the filter cannot be used.
	Compile(query string) compiledFilter
	External() bool
}

type compiledFilter interface {
	// Match returns highlight ranges and whether the line matched.
	Match(l *Line) ([][2]int, bool)
	// PostProcess is applied on the whole result set.
	PostProcess(lines []*Line) []*Line
}

// ---------- substring based filters -------------

type termMatcher interface {
	match(s string) [][2]int // positive matches (nil if none)
	contains(s string) bool
}

type literalMatcher struct {
	text       string
	ignoreCase bool
}

func (m literalMatcher) contains(s string) bool {
	if m.ignoreCase {
		return strings.Contains(strings.ToLower(s), strings.ToLower(m.text))
	}
	return strings.Contains(s, m.text)
}

func (m literalMatcher) match(s string) [][2]int {
	hay := s
	needle := m.text
	if m.ignoreCase {
		hay = strings.ToLower(s)
		needle = strings.ToLower(m.text)
		if len(hay) != len(s) {
			// lengths differ after folding; fall back to rune-wise matching
			return foldMatch(s, m.text)
		}
	}
	if needle == "" {
		return nil
	}
	var out [][2]int
	off := 0
	for {
		idx := strings.Index(hay[off:], needle)
		if idx < 0 {
			break
		}
		start := off + idx
		end := start + len(needle)
		out = append(out, [2]int{start, end})
		off = end
		if off >= len(hay) {
			break
		}
	}
	return out
}

// foldMatch performs case-insensitive matching rune by rune, returning byte offsets in s.
func foldMatch(s, needle string) [][2]int {
	nr := []rune(strings.ToLower(needle))
	if len(nr) == 0 {
		return nil
	}
	var out [][2]int
	sr := []rune(s)
	offs := make([]int, len(sr)+1)
	o := 0
	for i, r := range sr {
		offs[i] = o
		o += utf8.RuneLen(r)
	}
	offs[len(sr)] = o
	for i := 0; i+len(nr) <= len(sr); {
		ok := true
		for j := range nr {
			if unicode.ToLower(sr[i+j]) != nr[j] {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, [2]int{offs[i], offs[i+len(nr)]})
			i += len(nr)
		} else {
			i++
		}
	}
	return out
}

type regexMatcher struct {
	re *regexp.Regexp
}

func (m regexMatcher) contains(s string) bool { return m.re.MatchString(s) }
func (m regexMatcher) match(s string) [][2]int {
	locs := m.re.FindAllStringIndex(s, -1)
	if len(locs) == 0 {
		return nil
	}
