package main

import (
	"bufio"
	"io"
	"sync"
)

// Source reads the input lines.
type Source struct {
	mu       sync.Mutex
	lines    []*Line
	capacity int
	nullSep  bool
	ansi     bool
	maxScan  int
	nextID   int
	ready    chan struct{}
	done     chan struct{}
	readyOnce sync.Once
	notify   func()
}

func newSource(capacity int, nullSep, ansi bool, maxScanKB int) *Source {
	if maxScanKB <= 0 {
