)

const jumpKeys = "asdfghjklzxcvbnmqwertyuiop"

// layoutInfo captures the current screen geometry.
type layoutInfo struct {
	width    int
	height   int // total region height
	top      int // first row of the region
	perPage  int
	queryRow int
	statusRow int
	listTop  int
}

func (p *Peco) computeLayout() layoutInfo {
	w, h := p.screen.Size()
	var li layoutInfo
	li.width = w
	regionH := h
	top := 0
	if p.inline {
		regionH = p.inlineHeight(h)
		if regionH > h {
			regionH = h
		}
		top = h - regionH
	}
	li.height = regionH
	li.top = top
	listRows := regionH - 2
	if listRows < 1 {
		listRows = 1
	}
	li.perPage = listRows
	switch p.layout {
	case "bottom-up", "top-down-query-bottom":
		li.listTop = top
		li.queryRow = top + regionH - 2
		li.statusRow = top + regionH - 1
	default:
		li.queryRow = top
		li.listTop = top + 1
		li.statusRow = top + regionH - 1
	}
	return li
}

// inlineHeight computes the number of rows for inline mode given the terminal height.
func (p *Peco) inlineHeight(termH int) int {
	var rows int
	if p.heightPercent > 0 {
		rows = termH * p.heightPercent / 100
	} else {
		rows = p.heightLines + 2
	}
	if rows < 3 {
		rows = 3
	}
	if rows > termH {
		rows = termH
	}
	return rows
}

// mergeMatched computes the style for a matched segment over a base style.
func mergeMatched(base, matched tcell.Style) tcell.Style {
	bfg, bbg, _ := base.Decompose()
	mfg, mbg, mattr := matched.Decompose()
	_ = bfg
	return tcell.StyleDefault.Foreground(mfg).Background(bbg | mbg).Attributes(mattr)
}

func (p *Peco) putStr(x, y int, s string, st tcell.Style, maxX int) int {
	for _, r := range s {
		w := runewidth.RuneWidth(r)
		if w == 0 {
			continue
		}
		if x >= 0 && x < maxX {
			p.screen.SetContent(x, y, r, nil, st)
		}
		x += w
	}
	return x
}

func (p *Peco) fillRow(y, from, to int, st tcell.Style) {
	for x := from; x < to; x++ {
		p.screen.SetContent(x, y, ' ', nil, st)
	}
}

// draw renders the whole UI.
func (p *Peco) draw() {
	if p.screen == nil {
		return
	}
	li := p.computeLayout()
	p.lastLayout = li
	p.drawQuery(li)
	p.drawList(li)
	p.drawStatus(li)
	p.screen.Show()
}

func (p *Peco) drawQuery(li layoutInfo) {
	y := li.queryRow
	if y < 0 {
		return
	}
	w := li.width
	// prompt
	x := p.putStr(0, y, p.prompt, p.styles.Prompt, w)
	// clear the remainder with the query style
	p.fillRow(y, x, w, p.styles.Query)
	// space after the prompt
	if x < w {
		p.screen.SetContent(x, y, ' ', nil, p.styles.Query)
	}
	x++
	qstart := x
	cursorX := -1
	for i, r := range p.query {
		rw := runewidth.RuneWidth(r)
		st := p.styles.Query
		if i == p.caret {
			st = p.styles.QueryCursor
			cursorX = x
		}
		if rw == 0 {
			continue
		}
		if x < w {
			p.screen.SetContent(x, y, r, nil, st)
		}
		x += rw
	}
	if cursorX < 0 {
		cursorX = x
		if x < w {
			p.screen.SetContent(x, y, ' ', nil, p.styles.QueryCursor)
		}
	}
	_ = qstart
	// right side status
	total := p.current.Size()
	page := p.lineIdx / li.perPage
	maxPage := (total + li.perPage - 1) / li.perPage
	if maxPage < 1 {
		maxPage = 1
	}
	if page >= maxPage {
		page = maxPage - 1
	}
	status := fmt.Sprintf("%s [%d (%d/%d)]", p.currentFilter().Name(), total, page+1, maxPage)
	sw := runewidth.StringWidth(status)
	p.putStr(w-sw, y, status, p.styles.Basic, w)
	p.screen.ShowCursor(cursorX, y)
}

func (p *Peco) drawStatus(li layoutInfo) {
	y := li.statusRow
	if y < 0 || y == li.queryRow {
		return
	}
	w := li.width
	p.fillRow(y, 0, w, p.styles.Basic)
	msg := p.statusMsg
	if p.cfg.SuppressStatusMsg {
		msg = ""
	}
	if msg != "" {
		sw := runewidth.StringWidth(msg)
		st := p.styles.Basic.Bold(true).Reverse(true)
		p.putStr(w-sw, y, msg, st, w)
	}
}

// lineStyle returns the base style for the line at buffer index idx.
func (p *Peco) lineBaseStyle(idx int, l *Line) tcell.Style {
	if p.selectionPrefix == "" {
		if idx == p.lineIdx {
			return p.styles.Selected
		}
		if p.isSelected(idx, l) {
			return p.styles.SavedSelection
		}
	}
	if l.context {
		return p.styles.Context
	}
	return p.styles.Basic
}

func (p *Peco) drawList(li layoutInfo) {
	w := li.width
	total := p.current.Size()
	page := 0
	if li.perPage > 0 {
		page = p.lineIdx / li.perPage
	}
	start := page * li.perPage
	// compute max line width for scroll clamping
	maxW := 0
	for i := 0; i < li.perPage; i++ {
		idx := start + i
		if idx >= total {
			break
		}
		lw := displayWidth(p.current.LineAt(idx).display)
		if lw > maxW {
			maxW = lw
		}
	}
	p.maxLineWidth = maxW
	for i := 0; i < li.perPage; i++ {
		row := li.listTop + i
		if p.layout == "bottom-up" {
			row = li.listTop + li.perPage - 1 - i
		}
		if row < 0 || row >= li.top+li.height {
			continue
		}
		idx := start + i
		if idx >= total {
			p.fillRow(row, 0, w, p.styles.Basic)
			continue
		}
		l := p.current.LineAt(idx)
		p.drawLine(row, idx, l, li)
	}
}

func displayWidth(s string) int {
	col := 0
	for _, r := range s {
		if r == '\t' {
			col += 4 - col%4
			continue
		}
		col += runewidth.RuneWidth(r)
	}
	return col
}

func (p *Peco) drawLine(y, idx int, l *Line, li layoutInfo) {
	w := li.width
	base := p.lineBaseStyle(idx, l)
	x := 0
	if p.selectionPrefix != "" {
		pw := runewidth.StringWidth(p.selectionPrefix)
		var prefix string
		if idx == p.lineIdx {
			prefix = p.selectionPrefix
		} else if p.isSelected(idx, l) {
			prefix = "*"
		}
		px := p.putStr(0, y, prefix, base, w)
		for ; px < pw; px++ {
			if px < w {
				p.screen.SetContent(px, y, ' ', nil, base)
			}
		}
		if pw < w {
			p.screen.SetContent(pw, y, ' ', nil, base)
		}
		x = pw + 1
	}
	if p.singleKeyJump && p.showJumpPrefix {
		st := base.Bold(true).Reverse(true)
		if idx < len(jumpKeys) {
			if x < w {
				p.screen.SetContent(x, y, rune(jumpKeys[idx]), nil, st)
			}
		} else if x < w {
			p.screen.SetContent(x, y, ' ', nil, base)
		}
		if x+1 < w {
			p.screen.SetContent(x+1, y, ' ', nil, base)
		}
		x += 2
	}
	p.fillRow(y, x, w, base)
	// render the text
	useANSI := p.ansi && len(l.spans) > 0 && (p.selectionPrefix != "" || (idx != p.lineIdx && !p.isSelected(idx, l)))
	spanIdx := 0
	matchIdx := 0
	col := 0
	hoff := p.hoff
	for off, r := range l.display {
		// determine style
		st := base
		if useANSI {
			for spanIdx < len(l.spans) && l.spans[spanIdx].end <= off {
				spanIdx++
			}
			if spanIdx < len(l.spans) {
				sp := l.spans[spanIdx]
				if sp.start <= off && off < sp.end {
					bfg, bbg, battr := base.Decompose()
					fg, bg := bfg, bbg
					if sp.fg != tcell.ColorDefault {
						fg = sp.fg
					}
					if sp.bg != tcell.ColorDefault {
						bg = sp.bg
					}
					st = tcell.StyleDefault.Foreground(fg).Background(bg).Attributes(battr | sp.attrs)
				}
			}
		}
		for matchIdx < len(l.matches) && l.matches[matchIdx][1] <= off {
			matchIdx++
		}
		if matchIdx < len(l.matches) {
			m := l.matches[matchIdx]
			if m[0] <= off && off < m[1] {
				st = mergeMatched(st, p.styles.Matched)
			}
		}
		if r == '\t' {
			n := 4 - col%4
			for k := 0; k < n; k++ {
				sx := x + col - hoff
				if sx >= x && sx < w {
					p.screen.SetContent(sx, y, ' ', nil, st)
				}
				col++
			}
			continue
		}
		rw := runewidth.RuneWidth(r)
		if rw == 0 {
			continue
		}
		sx := x + col - hoff
		if sx >= x && sx+rw <= w {
			p.screen.SetContent(sx, y, r, nil, st)
		} else if sx >= x && sx < w {
			// partially visible wide char: leave blank
		}
		col += rw
	}
}

// statusText for debugging
func (p *Peco) debugString() string {
	var b strings.Builder
	fmt.Fprintf(&b, "query=%q caret=%d idx=%d total=%d", string(p.query), p.caret, p.lineIdx, p.current.Size())
	return b.String()
}
EOF
echo ok"}

