const version = "v0.5.11"

type zoomState struct {
	buffer  *Buffer
	lineIdx int
}

// Peco is the application state. All mutation happens on the main goroutine.
type Peco struct {
	opts   *Options
	cfg    *Config
	styles *StyleSet
	keymap *Keymap
	actions map[string]*Action

	filters   []Filter
	filterIdx int

	source     *Source
	frozen     []*Line
	current    *Buffer
	resultsFor string // query which produced current (empty if current is the base)
	isFiltered bool

	query      []rune
