	heightLines    int
	heightPercent  int
	onCancelError  bool
	sticky         bool
	execCmd        string
	printQuery     bool

	zoom *zoomState

	statusMsg string
	statusGen int

	keySeq []keySpec

	screen     tcell.Screen
	lastLayout layoutInfo

	events     chan func()
	filterGen  int
	filterCancel context.CancelFunc
	filterRunning bool
	queryTimer *time.Timer
