func (p *Peco) currentFilter() Filter {
	if p.filterIdx < 0 || p.filterIdx >= len(p.filters) {
		p.filterIdx = 0
	}
	return p.filters[p.filterIdx]
}

func (p *Peco) post(f func()) {
	select {
	case p.events <- f:
	default:
		go func() { p.events <- f }()
	}
}

// setStatus sets the status message. If timeout > 0 the message is cleared after it.
func (p *Peco) setStatus(msg string, timeout time.Duration) {
	p.statusGen++
	gen := p.statusGen
	p.statusMsg = msg
	if timeout > 0 {
		time.AfterFunc(timeout, func() {
			p.post(func() {
				if p.statusGen == gen {
					p.statusMsg = ""
				}
			})
		})
	}
}

func (p *Peco) clearStatus() {
	p.statusGen++
	p.statusMsg = ""
}

// base returns the unfiltered line set (frozen results or the source).
func (p *Peco) base() []*Line {
	if p.frozen != nil {
		return p.frozen
	}
	return p.source.Snapshot()
}

func (p *Peco) resetToBase() {
	p.current = &Buffer{lines: p.base()}
	p.resultsFor = ""
	p.isFiltered = false
	p.zoom = nil
	p.clampIndex()
}

func (p *Peco) clampIndex() {
	n := p.current.Size()
	if n == 0 {
		p.lineIdx = 0
		return
	}
	if p.lineIdx >= n {
		p.lineIdx = n - 1
	}
	if p.lineIdx < 0 {
		p.lineIdx = 0
	}
}

func (p *Peco) currentLine() *Line {
	return p.current.LineAt(p.lineIdx)
}

func (p *Peco) isSelected(idx int, l *Line) bool {
	if p.rangeStart >= 0 {
		lo, hi := p.rangeStart, p.lineIdx
		if lo > hi {
			lo, hi = hi, lo
		}
		if idx >= lo && idx <= hi {
			return true
		}
	}
	if l == nil {
		return false
	}
	_, ok := p.selection[l.id]
	return ok
}

func (p *Peco) perPage() int {
	pp := p.lastLayout.perPage
	if pp < 1 {
		pp = 1
	}
	return pp
}

// ---------------------------------------------------------------------
// query execution

func (p *Peco) queryString() string { return string(p.query) }

// scheduleQuery schedules a filter run after the debounce delay.
func (p *Peco) scheduleQuery() {
	p.hoff = 0
	p.queryTimerGen++
	gen := p.queryTimerGen
	time.AfterFunc(50*time.Millisecond, func() {
		p.post(func() {
			if p.queryTimerGen != gen {
				return
			}
			p.execQuery()
		})
	})
}

func (p *Peco) cancelFilter() {
	if p.filterCancel != nil {
		p.filterCancel()
		p.filterCancel = nil
	}
	p.filterRunning = false
}

// execQuery runs the current filter against the appropriate input.
func (p *Peco) execQuery() {
	p.cancelFilter()
	p.filterGen++
	gen := p.filterGen
	q := p.queryString()
	p.zoom = nil
	if strings.TrimSpace(q) == "" {
		p.resetToBase()
		p.clearStatus()
		p.rerunPending = false
		p.afterQuery()
		return
	}
	var input []*Line
	if p.isFiltered && p.resultsFor != "" && isRefinement(p.resultsFor, q) {
		input = p.current.lines
	} else {
		input = p.base()
	}
	if !p.sticky {
		p.selection = map[int]*Line{}
	}
	p.setStatus("Running query...", 0)
	filter := p.currentFilter()
	cf := filter.Compile(q)
	p.current = &Buffer{}
	p.isFiltered = true
	p.resultsFor = q
	ctx, cancel := context.WithCancel(context.Background())
	p.filterCancel = cancel
	p.filterRunning = true
	go p.runFilter(ctx, gen, filter, cf, input, q)
}

func (p *Peco) runFilter(ctx context.Context, gen int, f Filter, cf compiledFilter, input []*Line, q string) {
	var all []*Line
	emit := func(chunk []*Line, final bool) {
		p.post(func() {
			if p.filterGen != gen {
				return
			}
			if len(chunk) > 0 {
				p.current.lines = append(p.current.lines, chunk...)
			}
			if final {
				if pp, ok := cf.(interface{ PostProcess([]*Line) []*Line }); ok {
					p.current.lines = pp.PostProcess(p.current.lines)
				}
				p.filterRunning = false
				p.filterCancel = nil
				p.clampIndex()
				p.clearStatus()
				p.afterQuery()
			}
		})
	}
	if ext, ok := cf.(*externalCompiled); ok {
		th := ext.f.threshold
		if th <= 0 {
			th = 100
		}
		for i := 0; i < len(input); i += th {
			if ctx.Err() != nil {
				return
			}
			end := i + th
			if end > len(input) {
				end = len(input)
			}
			res := ext.run(ctx, input[i:end], p.source.NextID)
			if ctx.Err() != nil {
				return
			}
			emit(res, false)
		}
		emit(nil, true)
		return
	}
	_ = all
	const chunkSize = 20000
	var pending []*Line
	last := time.Now()
	for i, l := range input {
		if i%1024 == 0 && ctx.Err() != nil {
			return
		}
		m, ok := cf.Match(l)
		if ok {
			pending = append(pending, l.withMatches(m))
		}
		if len(pending) >= chunkSize || (len(pending) > 0 && time.Since(last) > 50*time.Millisecond) {
			emit(pending, false)
			pending = nil
			last = time.Now()
		}
	}
	if ctx.Err() != nil {
		return
	}
	emit(pending, true)
}

// afterQuery runs startup checks once the initial query has finished.
func (p *Peco) afterQuery() {
	p.initialQueryDone = true
	p.maybeStartupChecks()
	if p.rerunPending {
		p.rerunPending = false
		if p.queryString() != "" {
			p.execQuery()
		}
	}
}

// maybeStartupChecks handles --select-1 / --select-all once input and the
// initial query are complete.
func (p *Peco) maybeStartupChecks() {
	if p.startupChecked || !p.sourceDoneSeen || !p.initialQueryDone || p.filterRunning {
		return
	}
	p.startupChecked = true
	if p.opts.Select1 {
		if p.current.Size() == 1 {
			p.lineIdx = 0
			p.finish()
			return
		}
		if p.source.Size() == 1 {
			l := p.source.Snapshot()[0]
			p.outputLines = p.collectOutput([]*Line{l})
			p.exit(0)
			return
		}
	}
	if p.opts.SelectAll {
		for _, l := range p.current.lines {
			p.selection[l.id] = l
		}
		p.finish()
	}
}

// onSourceTick is called periodically while input is being read.
func (p *Peco) onSourceTick() {
	if p.queryString() == "" {
		if !p.isFiltered {
			p.resetToBase()
		}
		return
	}
	if p.filterRunning {
		p.rerunPending = true
		return
	}
	p.execQuery()
}

func (p *Peco) onSourceDone() {
	p.sourceDoneSeen = true
	if p.queryString() == "" {
		if !p.isFiltered {
			p.resetToBase()
		}
		p.initialQueryDone = true
		p.maybeStartupChecks()
		return
	}
	if p.filterRunning {
		p.rerunPending = true
		return
	}
	p.execQuery()
}

// ---------------------------------------------------------------------
// finishing

func (p *Peco) collectOutput(lines []*Line) []string {
	var out []string
	if p.printQuery {
		out = append(out, p.queryString())
	}
	for _, l := range lines {
		out = append(out, l.output)
	}
	return out
}

func (p *Peco) selectedLines() []*Line {
	var lines []*Line
	seen := map[int]bool{}
	if p.rangeStart >= 0 {
		lo, hi := p.rangeStart, p.lineIdx
		if lo > hi {
			lo, hi = hi, lo
		}
		for i := lo; i <= hi; i++ {
			if l := p.current.LineAt(i); l != nil && !l.context {
				lines = append(lines, l)
				seen[l.id] = true
			}
		}
	}
	for id, l := range p.selection {
		if !seen[id] {
			lines = append(lines, l)
		}
	}
	sort.Slice(lines, func(i, j int) bool { return lines[i].id < lines[j].id })
	return lines
}

func (p *Peco) finish() {
	lines := p.selectedLines()
	if len(lines) == 0 {
		if l := p.currentLine(); l != nil && !l.context {
			lines = []*Line{l}
		}
	}
	if p.execCmd != "" {
		p.runExec(lines)
		return
	}
	p.outputLines = p.collectOutput(lines)
	p.exit(0)
}

func (p *Peco) cancel() {
	if p.onCancelError {
		p.exit(1)
	} else {
		p.exit(0)
	}
}

func (p *Peco) exit(code int) {
	p.exited = true
	p.exitCode = code
	p.cancelFilter()
}

func (p *Peco) runExec(lines []*Line) {
	p.setStatus("Executing "+p.execCmd, 0)
	p.draw()
	var in strings.Builder
	for _, l := range lines {
		in.WriteString(l.output)
		in.WriteByte('\n')
	}
	if p.screen != nil {
		p.screen.Suspend()
	}
	cmd := shellCommand(p.execCmd)
	cmd.Stdin = strings.NewReader(in.String())
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	if p.screen != nil {
		p.screen.Resume()
	}
	p.clearStatus()
}

// ---------------------------------------------------------------------
// setup helpers

func parseHeightSpec(s string) (lines, percent int, err error) {
	if strings.HasSuffix(s, "%") {
		n, e := strconv.Atoi(strings.TrimSuffix(s, "%"))
		if e != nil {
			return 0, 0, fmt.Errorf("invalid height specification: %q", s)
		}
		if n <= 0 {
			return 0, 0, fmt.Errorf("height must be positive: %q", s)
		}
		if n > 100 {
			return 0, 0, fmt.Errorf("height percentage must not exceed 100: %q", s)
		}
		return 0, n, nil
	}
	n, e := strconv.Atoi(s)
	if e != nil {
		return 0, 0, fmt.Errorf("invalid height specification: %q", s)
	}
	if n <= 0 {
		return 0, 0, fmt.Errorf("height must be positive: %q", s)
	}
	return n, 0, nil
}
