		if len(pending) >= chunkSize || (len(pending) > 0 && time.Since(last) > 50*time.Millisecond) {
			emit(pending, false)
			pending = nil
			last = time.Now()
		}
	}
	if ctx.Err() != nil {
		return
	}
	emit(pending, true)
}

// afterQuery runs startup checks once the initial query has finished.
func (p *Peco) afterQuery() {
	p.initialQueryDone = true
	p.maybeStartupChecks()
	if p.rerunPending {
		p.rerunPending = false
		if p.queryString() != "" {
			p.execQuery()
		}
	}
}

// maybeStartupChecks handles --select-1 / --select-all once input and the
// initial query are complete.
func (p *Peco) maybeStartupChecks() {
	if p.startupChecked || !p.sourceDoneSeen || !p.initialQueryDone || p.filterRunning {
		return
	}
	p.startupChecked = true
	if p.opts.Select1 {
		if p.current.Size() == 1 {
			p.lineIdx = 0
			p.finish()
			return
		}
		if p.source.Size() == 1 {
			l := p.source.Snapshot()[0]
			p.outputLines = p.collectOutput([]*Line{l})
			p.exit(0)
			return
		}
	}
	if p.opts.SelectAll {
		for _, l := range p.current.lines {
			p.selection[l.id] = l
		}
		p.finish()
	}
}

// onSourceTick is called periodically while input is being read.
func (p *Peco) onSourceTick() {
	if p.queryString() == "" {
		if !p.isFiltered {
			p.resetToBase()
		}
		return
	}
	if p.filterRunning {
		p.rerunPending = true
		return
	}
	p.execQuery()
}

func (p *Peco) onSourceDone() {
	p.sourceDoneSeen = true
	if p.queryString() == "" {
		if !p.isFiltered {
			p.resetToBase()
		}
		p.initialQueryDone = true
		p.maybeStartupChecks()
		return
	}
	if p.filterRunning {
		p.rerunPending = true
		return
	}
	p.execQuery()
}

// ---------------------------------------------------------------------
// finishing

func (p *Peco) collectOutput(lines []*Line) []string {
	var out []string
	if p.printQuery {
		out = append(out, p.queryString())
	}
	for _, l := range lines {
		out = append(out, l.output)
	}
	return out
}

func (p *Peco) selectedLines() []*Line {
	var lines []*Line
	seen := map[int]bool{}
	if p.rangeStart >= 0 {
		lo, hi := p.rangeStart, p.lineIdx
		if lo > hi {
			lo, hi = hi, lo
		}
		for i := lo; i <= hi; i++ {
			if l := p.current.LineAt(i); l != nil && !l.context {
				lines = append(lines, l)
				seen[l.id] = true
			}
		}
	}
	for id, l := range p.selection {
		if !seen[id] {
			lines = append(lines, l)
		}
	}
	sort.Slice(lines, func(i, j int) bool { return lines[i].id < lines[j].id })
	return lines
}

func (p *Peco) finish() {
	lines := p.selectedLines()
	if len(lines) == 0 {
		if l := p.currentLine(); l != nil && !l.context {
			lines = []*Line{l}
		}
	}
	if p.execCmd != "" {
		p.runExec(lines)
		return
	}
	p.outputLines = p.collectOutput(lines)
	p.exit(0)
}

func (p *Peco) cancel() {
	if p.onCancelError {
		p.exit(1)
	} else {
		p.exit(0)
	}
}

func (p *Peco) exit(code int) {
	p.exited = true
	p.exitCode = code
	p.cancelFilter()
}

func (p *Peco) runExec(lines []*Line) {
	p.setStatus("Executing "+p.execCmd, 0)
	p.draw()
	var in strings.Builder
	for _, l := range lines {
		in.WriteString(l.output)
		in.WriteByte('\n')
	}
	if p.screen != nil {
		p.screen.Suspend()
	}
	cmd := shellCommand(p.execCmd)
	cmd.Stdin = strings.NewReader(in.String())
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	if p.screen != nil {
		p.screen.Resume()
	}
	p.clearStatus()
}

// ---------------------------------------------------------------------
// setup helpers

func parseHeightSpec(s string) (lines, percent int, err error) {
	if strings.HasSuffix(s, "%") {
		n, e := strconv.Atoi(strings.TrimSuffix(s, "%"))
		if e != nil {
			return 0, 0, fmt.Errorf("invalid height specification: %q", s)
		}
		if n <= 0 {
			return 0, 0, fmt.Errorf("height must be positive: %q", s)
		}
		if n > 100 {
			return 0, 0, fmt.Errorf("height percentage must not exceed 100: %q", s)
		}
		return 0, n, nil
	}
	n, e := strconv.Atoi(s)
	if e != nil {
		return 0, 0, fmt.Errorf("invalid height specification: %q", s)
	}
	if n <= 0 {
		return 0, 0, fmt.Errorf("height must be positive: %q", s)
	}
	return n, 0, nil
}
