// ---- query editing ----

func (p *Peco) queryChanged() {
	p.scheduleQuery()
}

func (p *Peco) actForwardChar() {
	if p.caret < len(p.query) {
		p.caret++
	}
}

func (p *Peco) actBackwardChar() {
	if p.caret > 0 {
		p.caret--
	}
}

func isSpace(r rune) bool { return unicode.IsSpace(r) }

func (p *Peco) actForwardWord() {
	n := len(p.query)
	i := p.caret
	for i < n && !isSpace(p.query[i]) {
		i++
	}
	for i < n && isSpace(p.query[i]) {
		i++
	}
	p.caret = i
}

func (p *Peco) actBackwardWord() {
	i := p.caret
	for i > 0 && isSpace(p.query[i-1]) {
		i--
	}
	for i > 0 && !isSpace(p.query[i-1]) {
		i--
	}
	p.caret = i
}

func (p *Peco) actBeginningOfLine() { p.caret = 0 }
func (p *Peco) actEndOfLine()       { p.caret = len(p.query) }

func (p *Peco) actEndOfFile() {
	if len(p.query) == 0 {
		p.actCancel()
		return
	}
	p.actDeleteForwardChar()
}

func (p *Peco) actDeleteForwardChar() {
	if p.caret < len(p.query) {
		p.query = append(p.query[:p.caret], p.query[p.caret+1:]...)
		p.queryChanged()
	}
}

func (p *Peco) actDeleteBackwardChar() {
	if p.caret > 0 {
		p.query = append(p.query[:p.caret-1], p.query[p.caret:]...)
		p.caret--
		p.queryChanged()
	}
}

func (p *Peco) actDeleteForwardWord() {
	n := len(p.query)
	if p.caret >= n {
		return
	}
	i := p.caret
	sp := isSpace(p.query[i])
	for i < n && isSpace(p.query[i]) == sp {
		i++
	}
	p.query = append(p.query[:p.caret], p.query[i:]...)
	p.queryChanged()
}

func (p *Peco) actDeleteBackwardWord() {
	if p.caret == 0 {
		return
	}
	i := p.caret
	sp := isSpace(p.query[i-1])
	for i > 0 && isSpace(p.query[i-1]) == sp {
		i--
	}
	p.query = append(p.query[:i], p.query[p.caret:]...)
	p.caret = i
	p.queryChanged()
}

func (p *Peco) actKillBeginningOfLine() {
	if p.caret == 0 {
		return
	}
	p.query = append([]rune{}, p.query[p.caret:]...)
	p.caret = 0
	p.queryChanged()
}

func (p *Peco) actKillEndOfLine() {
	if p.caret >= len(p.query) {
		return
	}
	p.query = p.query[:p.caret]
	p.queryChanged()
}

func (p *Peco) actDeleteAll() {
	if len(p.query) == 0 {
		return
	}
	p.query = nil
	p.caret = 0
	p.queryChanged()
}

func (p *Peco) insertRune(r rune) {
	q := make([]rune, 0, len(p.query)+1)
	q = append(q, p.query[:p.caret]...)
	q = append(q, r)
	q = append(q, p.query[p.caret:]...)
	p.query = q
	p.caret++
	p.queryChanged()
}

// ---- movement ----

func (p *Peco) moveBy(delta int) {
	n := p.current.Size()
	if n == 0 {
		p.lineIdx = 0
		return
	}
	idx := p.lineIdx + delta
	if idx < 0 {
		idx = n - 1
	} else if idx >= n {
		idx = 0
	}
	p.lineIdx = idx
}

func (p *Peco) actSelectDown() {
	if p.layout == "bottom-up" {
		p.moveBy(-1)
	} else {
		p.moveBy(1)
	}
}

func (p *Peco) actSelectUp() {
	if p.layout == "bottom-up" {
		p.moveBy(1)
	} else {
		p.moveBy(-1)
	}
}

func (p *Peco) pageDown() {
	n := p.current.Size()
	if n == 0 {
		return
	}
	pp := p.perPage()
	maxPage := (n + pp - 1) / pp
	page := p.lineIdx / pp
	if page >= maxPage-1 {
		p.lineIdx = 0
		return
	}
	idx := p.lineIdx + pp
	if idx >= n {
		idx = n - 1
	}
	p.lineIdx = idx
}

func (p *Peco) pageUp() {
	n := p.current.Size()
	if n == 0 {
		return
	}
	pp := p.perPage()
	page := p.lineIdx / pp
	if page == 0 {
		p.lineIdx = n - 1
		return
	}
	idx := p.lineIdx - pp
	if idx < 0 {
		idx = 0
	}
	p.lineIdx = idx
}

func (p *Peco) actScrollPageDown() {
	if p.layout == "bottom-up" {
		p.pageUp()
	} else {
		p.pageDown()
	}
}

func (p *Peco) actScrollPageUp() {
	if p.layout == "bottom-up" {
		p.pageDown()
	} else {
		p.pageUp()
	}
}

func (p *Peco) actScrollFirstItem() { p.lineIdx = 0 }
func (p *Peco) actScrollLastItem() {
	n := p.current.Size()
	if n > 0 {
		p.lineIdx = n - 1
	} else {
		p.lineIdx = 0
	}
}

func (p *Peco) actScrollLeft() {
	w := p.lastLayout.width
	p.hoff -= w / 2
	if p.hoff < 0 {
		p.hoff = 0
	}
}

func (p *Peco) actScrollRight() {
	w := p.lastLayout.width
	max := p.maxLineWidth - w
	if max < 0 {
		max = 0
	}
	p.hoff += w / 2
	if p.hoff > max {
		p.hoff = max
	}
}

// ---- selection ----

func (p *Peco) toggleCurrent() {
	l := p.currentLine()
	if l == nil || l.context {
		return
	}
	if _, ok := p.selection[l.id]; ok {
		delete(p.selection, l.id)
	} else {
		p.selection[l.id] = l
	}
}

func (p *Peco) actToggleSelection() { p.toggleCurrent() }

func (p *Peco) actToggleSelectionAndSelectNext() {
	p.toggleCurrent()
	p.moveBy(1)
}

func (p *Peco) actInvertSelection() {
	for _, l := range p.current.lines {
		if l.context {
			continue
		}
		if _, ok := p.selection[l.id]; ok {
			delete(p.selection, l.id)
		} else {
			p.selection[l.id] = l
		}
	}
}

func (p *Peco) actSelectNone() {
	p.selection = map[int]*Line{}
	p.rangeStart = -1
}

func (p *Peco) actSelectAll() {
	for _, l := range p.current.lines {
		if !l.context {
			p.selection[l.id] = l
		}
	}
}

func (p *Peco) actSelectVisible() {
	pp := p.perPage()
	start := (p.lineIdx / pp) * pp
	for i := start; i < start+pp; i++ {
		l := p.current.LineAt(i)
		if l == nil {
			break
		}
		if !l.context {
			p.selection[l.id] = l
		}
	}
}

func (p *Peco) commitRange() {
	if p.rangeStart < 0 {
		return
	}
	lo, hi := p.rangeStart, p.lineIdx
	if lo > hi {
		lo, hi = hi, lo
	}
	for i := lo; i <= hi; i++ {
		if l := p.current.LineAt(i); l != nil && !l.context {
			p.selection[l.id] = l
		}
	}
	p.rangeStart = -1
}

func (p *Peco) actToggleRangeMode() {
	if p.rangeStart >= 0 {
		p.commitRange()
		return
	}
	if p.current.Size() == 0 {
		return
	}
	p.rangeStart = p.lineIdx
}

func (p *Peco) actCancelRangeMode() {
	p.commitRange()
}

func (p *Peco) findSelection(dir int) {
	n := p.current.Size()
	if n == 0 {
		return
	}
	for step := 1; step <= n; step++ {
		idx := ((p.lineIdx+dir*step)%n + n) % n
		l := p.current.LineAt(idx)
		if l != nil {
			if _, ok := p.selection[l.id]; ok {
				p.lineIdx = idx
				return
			}
		}
	}
}

func (p *Peco) actGoToNextSelection()     { p.findSelection(1) }
func (p *Peco) actGoToPreviousSelection() { p.findSelection(-1) }

// ---- filters & views ----

func (p *Peco) actRotateFilter() {
	p.filterIdx = (p.filterIdx + 1) % len(p.filters)
	p.resultsFor = ""
	if p.queryString() != "" {
		p.execQuery()
	}
}

func (p *Peco) actBackToInitialFilter() {
	p.filterIdx = 0
	p.resultsFor = ""
	if p.queryString() != "" {
		p.execQuery()
	}
}

func (p *Peco) actToggleQuery() {
	if len(p.query) > 0 {
		p.savedQuery = append([]rune{}, p.query...)
		p.query = nil
		p.caret = 0
		p.queryTimerGen++
		p.cancelFilter()
		p.resetToBase()
		p.clearStatus()
		return
	}
	if len(p.savedQuery) == 0 {
		return
	}
	p.query = append([]rune{}, p.savedQuery...)
	p.savedQuery = nil
	p.execQuery()
}

func (p *Peco) actViewAround() {
	if len(p.query) == 0 {
		return
	}
	cur := p.currentLine()
	p.query = nil
	p.caret = 0
	p.queryTimerGen++
	p.cancelFilter()
	p.resetToBase()
	p.clearStatus()
	if cur != nil {
		for i, l := range p.current.lines {
			if l.id == cur.id {
				p.lineIdx = i
				break
			}
		}
	}
}

func (p *Peco) actFreezeResults() {
	p.queryTimerGen++
	p.cancelFilter()
	lines := make([]*Line, len(p.current.lines))
	copy(lines, p.current.lines)
	p.frozen = lines
	p.query = nil
	p.caret = 0
	p.current = &Buffer{lines: lines}
	p.resultsFor = ""
	p.isFiltered = false
	p.zoom = nil
	p.clampIndex()
	p.setStatus("Results frozen", 0)
}

func (p *Peco) actUnfreezeResults() {
	if p.frozen == nil {
		p.setStatus("No frozen results", 0)
		return
	}
	p.frozen = nil
	p.queryTimerGen++
	p.cancelFilter()
	p.query = nil
	p.caret = 0
	p.resetToBase()
	p.setStatus("Results unfrozen", 0)
}

func (p *Peco) actZoomIn() {
	if p.zoom != nil {
		p.setStatus("Already zoomed in", 0)
		return
	}
	if !p.isFiltered || len(p.query) == 0 {
		p.setStatus("Nothing to zoom into", 0)
		return
	}
	base := p.base()
	pos := map[int]int{}
	for i, l := range base {
		pos[l.id] = i
	}
	const ctxLines = 3
	type rng struct{ lo, hi int }
	var ranges []rng
	matched := map[int]*Line{}
	for _, l := range p.current.lines {
		bi, ok := pos[l.id]
		if !ok {
			continue
		}
		matched[l.id] = l
		lo, hi := bi-ctxLines, bi+ctxLines
		if lo < 0 {
			lo = 0
		}
		if hi > len(base)-1 {
			hi = len(base) - 1
		}
		if len(ranges) > 0 && lo <= ranges[len(ranges)-1].hi+1 {
			if hi > ranges[len(ranges)-1].hi {
				ranges[len(ranges)-1].hi = hi
			}
		} else {
			ranges = append(ranges, rng{lo, hi})
		}
	}
	cur := p.currentLine()
	var lines []*Line
	newIdx := 0
	for _, r := range ranges {
		for i := r.lo; i <= r.hi; i++ {
			bl := base[i]
			if ml, ok := matched[bl.id]; ok {
				if cur != nil && cur.id == bl.id {
					newIdx = len(lines)
				}
				lines = append(lines, ml)
			} else {
				lines = append(lines, bl.asContext())
			}
		}
	}
	p.zoom = &zoomState{buffer: p.current, lineIdx: p.lineIdx}
	p.current = &Buffer{lines: lines}
	p.lineIdx = newIdx
}

func (p *Peco) actZoomOut() {
	if p.zoom == nil {
		p.setStatus("Not zoomed in", 0)
		return
	}
	p.current = p.zoom.buffer
	p.lineIdx = p.zoom.lineIdx
	p.zoom = nil
	p.clampIndex()
}

func (p *Peco) actToggleSingleKeyJump() {
	p.singleKeyJump = !p.singleKeyJump
}

func (p *Peco) actRefreshScreen() {
	if p.screen != nil {
		p.screen.Sync()
	}
	if p.queryString() != "" {
		p.resultsFor = ""
		p.execQuery()
	}
}

func (p *Peco) actFinish() { p.finish() }

func (p *Peco) actCancel() {
	if p.rangeStart >= 0 {
		p.commitRange()
		return
	}
	p.cancel()
}
EOF
echo ok"}

