		fmt.Fprintf(os.Stderr, "Error: failed to setup peco: %s\n", err.Error())
		return 1
	}

	// input source
	var reader *os.File
	if len(opts.Args) > 0 {
		f, err := os.Open(opts.Args[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: failed to setup input source: failed to open file for input: %s\n", err.Error())
