			fmt.Fprintln(os.Stderr, "Error: failed to setup input source: you must supply something to work with via filename or stdin")
			return 1
		}
		reader = os.Stdin
	}

	p.source = newSource(opts.BufferSize, p.nullSep, p.ansi, p.cfg.MaxScanBufferSize)
	go p.source.Read(reader)

	// wait until the first line (or EOF) arrives
	<-p.source.ready

	if opts.SelectAll && strings.TrimSpace(opts.Query) == "" {
		<-p.source.done
		if p.source.Size() > 0 {
			lines := p.source.Snapshot()
			p.outputLines = p.collectOutput(lines)
			p.writeOutput()
			return 0
		}
