func (p *Peco) writeOutput() {
	if len(p.outputLines) == 0 {
		return
	}
	w := bufio.NewWriter(os.Stdout)
	for _, l := range p.outputLines {
		w.WriteString(l)
		w.WriteByte('\n')
	}
	w.Flush()
