	p.filters = builtinFilters(cfg.FuzzyLongestSort)
	for name, cf := range cfg.CustomFilter {
		args := cf.Args
		if args == nil {
			args = []string{"$QUERY"}
		}
		p.filters = append(p.filters, &externalFilter{
			name: name, cmd: cf.Cmd, args: args, threshold: cf.BufferThreshold,
			nullSep: p.nullSep, ansi: p.ansi,
