	if err := p.buildActions(); err != nil {
		return fmt.Errorf("failed to apply configuration: failed to populate keymap: %s", err.Error())
	}
	km, err := buildKeymap(cfg, p.actions)
	if err != nil {
		return fmt.Errorf("failed to apply configuration: failed to populate keymap: %s", err.Error())
	}
	p.keymap = km

	initialFilter := cfg.InitialFilter
	if p.opts.InitialFilter != "" {
		initialFilter = p.opts.InitialFilter
	}
	if initialFilter != "" {
		found := false
		for i, f := range p.filters {
			if f.Name() == initialFilter {
				p.filterIdx = i
				found = true
				break
			}
		}
		if !found {
			return fmt.Errorf("failed to apply configuration: failed to populate initial filter: failed to set filter: specified filter was not found")
		}
	}

	onCancel := string(cfg.OnCancel)
	if p.opts.OnCancel != "" {
		switch p.opts.OnCancel {
