func (cb *cellBuf) set(x int, r rune, st tcell.Style) {
	if x >= 0 && x < len(cb.runes) {
		cb.runes[x] = r
		cb.styles[x] = st
	}
}

func (cb *cellBuf) putStr(x int, s string, st tcell.Style) int {
	for _, r := range s {
		w := runewidth.RuneWidth(r)
		if w == 0 {
			continue
		}
		cb.set(x, r, st)
		for k := 1; k < w; k++ {
			cb.set(x+k, 0, st)
		}
		x += w
	}
	return x
}

func (p *Peco) flushCellBuf(y int, cb *cellBuf) {
	for x := 0; x < len(cb.runes); x++ {
		if cb.runes[x] == 0 {
			continue // continuation of a wide character
		}
		p.screen.SetContent(x, y, cb.runes[x], nil, cb.styles[x])
	}
}

func (p *Peco) drawLine(y, idx int, l *Line, li layoutInfo) {
	w := li.width
	base := p.lineBaseStyle(idx, l)
	cb := newCellBuf(w, base)
	x := 0
	if p.selectionPrefix != "" {
		pw := runewidth.StringWidth(p.selectionPrefix)
		var prefix string
		if idx == p.lineIdx {
			prefix = p.selectionPrefix
		} else if p.isSelected(idx, l) {
			prefix = "*"
		}
		cb.putStr(0, prefix, base)
		x = pw + 1
	}
	if p.singleKeyJump && p.showJumpPrefix {
		st := base.Bold(true).Reverse(true)
		if idx < len(jumpKeys) {
			cb.set(x, rune(jumpKeys[idx]), st)
		}
		x += 2
	}
	// render the text
	useANSI := p.ansi && len(l.spans) > 0 && (p.selectionPrefix != "" || (idx != p.lineIdx && !p.isSelected(idx, l)))
	spanIdx := 0
	matchIdx := 0
	col := 0
	hoff := p.hoff
	for off, r := range l.display {
		st := base
		if useANSI {
			for spanIdx < len(l.spans) && l.spans[spanIdx].end <= off {
				spanIdx++
			}
			if spanIdx < len(l.spans) {
				sp := l.spans[spanIdx]
				if sp.start <= off && off < sp.end {
					bfg, bbg, battr := base.Decompose()
					fg, bg := bfg, bbg
					if sp.fg != tcell.ColorDefault {
						fg = sp.fg
					}
					if sp.bg != tcell.ColorDefault {
						bg = sp.bg
					}
					st = makeStyle(fg, bg, battr|sp.attrs)
				}
			}
		}
		for matchIdx < len(l.matches) && l.matches[matchIdx][1] <= off {
			matchIdx++
		}
		if matchIdx < len(l.matches) {
			m := l.matches[matchIdx]
			if m[0] <= off && off < m[1] {
				st = mergeMatched(st, p.styles.Matched)
			}
		}
		if r == '\\t' {
			n := 4 - col%4
			for k := 0; k < n; k++ {
				sx := x + col - hoff
				if sx >= x {
					cb.set(sx, ' ', st)
				}
				col++
			}
			continue
